class Node:
    def __init__(self):
        self.children = []
        self.lockedBy = -1  # -1 means unlocked

class LockingTree:
    def __init__(self, parent):
        self.parent = parent
        self.nodes = [Node() for _ in range(len(parent))]
        for i in range(1, len(parent)):
            self.nodes[parent[i]].children.append(i)

    def lock(self, num, user):
        if self.nodes[num].lockedBy != -1:
            return False
        self.nodes[num].lockedBy = user
        return True

    def unlock(self, num, user):
        if self.nodes[num].lockedBy != user:
            return False
        self.nodes[num].lockedBy = -1
        return True

    def upgrade(self, num, user):
        # Node itself must be unlocked
        if self.nodes[num].lockedBy != -1:
            return False
        # Check for locked ancestors
        ancestor = self.parent[num]
        while ancestor != -1:
            if self.nodes[ancestor].lockedBy != -1:
                return False
            ancestor = self.parent[ancestor]
        # Collect locked descendants (iterative DFS to avoid deep recursion)
        locked_nodes = []
        stack = list(self.nodes[num].children)
        while stack:
            node = stack.pop()
            if self.nodes[node].lockedBy != -1:
                locked_nodes.append(node)
            stack.extend(self.nodes[node].children)
        if not locked_nodes:
            return False
        # Unlock all locked descendants
        for ln in locked_nodes:
            self.nodes[ln].lockedBy = -1
        # Lock this node
        self.nodes[num].lockedBy = user
        return True
